import{z as l,x as p,o as e,c as h,q as A,j as o,D as t,d as E,s,S as B,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"协整秩选择","description":"","frontmatter":{"title":"协整秩选择","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/coint-rank.md","filePath":"quant/coint-rank.md","lastUpdated":1791063341000}'),i={name:"quant/coint-rank.md"};function d(m,a,u,c,C,D){const n=p("Mermaid");return e(),h("div",null,[a[2]||(a[2]=A('<h1 id="协整秩选择" tabindex="-1">协整秩选择 <a class="header-anchor" href="#协整秩选择" aria-label="Permalink to &quot;协整秩选择&quot;">​</a></h1><div class="epigraph"><p>迹检验给出的是「至少还有几条长期关系」的顺序决策；交易要的是一条波动能覆盖成本、样本外仍回调的价差。秩选对了只说明空间的维数，不说明你该交易空间里的哪一个方向。</p><footer>—— Johansen, Journal of Economic Dynamics and Control 1988 与 Econometrica 1991；信息准则选秩见 Aznar and Salvador, Journal of Time Series Analysis, 2002 一类讨论</footer></div><p><a href="/quant/kalman-spread">上一课</a>把状态写成价差的均衡水平或潜在 OU，可交易信号用预测步偏离；新息若仍像单位根，问题在 \\(\\beta\\) 或协整破裂，不是把均值再平滑一次。缺口是篮子的秩。两资产配对默认 \\(r=1\\) 或 \\(0\\)，三只以上 \\(r\\) 必须显式选择：\\(r=0\\) 不该做水平组合，\\(r\\) 过大则把近单位根方向当成可交易价差。本课写秩作为交易规格如何选。不重写 Kalman 的 \\(Q,R\\)。后课对冲比断裂默认已经读完：顺序检验不是后验概率。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(p\\) 维 \\(I(1)\\) 系统的协整秩 \\(r\\) 是 \\(\\Pi=\\alpha\\beta&#39;\\) 的列空间维数。\\(r\\) 选小了，真实平稳组合被留在差分里，你可能把一条可交易价差扔掉，或更糟：在 \\(r=0\\) 时仍用水平回归硬造价差。\\(r\\) 选大了，空间里混进弱根，对应的「价差」半衰期极长、接近随机游走，<a href="/quant/ou-spread">OU</a> 的 \\(\\kappa\\) 估出来接近 0 却仍被拿去开仓。Johansen 迹检验从 \\(r_0=0\\) 往上，第一次不拒绝当作 \\(\\hat r\\)。有限样本里滞后阶、确定性项、厚尾都会改尺寸，两个检验还经常给出不同的 \\(\\hat r\\)。</p><p><span class="marginnote">直觉类比：把协整秩想成房间里「被橡皮筋拴在一起」的绳组数。\\(r=1\\) 表示只有一条橡皮筋把某几个价格拴住，拉开会弹回；\\(r=0\\) 表示没有任何橡皮筋，价格各自游走。在 \\(r=0\\) 时硬连线，就是把两根自由摆动的绳子当作会弹回来——价差只会越拉越远。</span></p>',6)),(e(),o(B,null,{default:t(()=>[s(n,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20EST%5B%22%E6%A0%B7%E6%9C%AC%E5%86%85%E4%BC%B0%E8%AE%A1%E7%A7%A9%20r%22%5D%20--%3E%20SMALL%5B%22r%20%E9%80%89%E5%B0%8F%22%5D%0A%20%20EST%20--%3E%20LARGE%5B%22r%20%E9%80%89%E5%A4%A7%22%5D%0A%20%20SMALL%20--%3E%20MISS%5B%22%E7%9C%9F%E5%B9%B3%E7%A8%B3%E7%BB%84%E5%90%88%E7%95%99%E5%9C%A8%E5%B7%AE%E5%88%86%E9%87%8C%22%5D%0A%20%20MISS%20--%3E%20LOSE%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E4%BB%B7%E5%B7%AE%E8%A2%AB%E6%89%94%E6%8E%89%22%5D%0A%20%20LARGE%20--%3E%20WEAK%5B%22%E5%BC%B1%E6%A0%B9%E6%B7%B7%E8%BF%9B%E5%8D%8F%E6%95%B4%E7%A9%BA%E9%97%B4%22%5D%0A%20%20WEAK%20--%3E%20SLOW%5B%22%E5%81%87%E4%BB%B7%E5%B7%AE%E5%8D%8A%E8%A1%B0%E6%9C%9F%E6%9E%81%E9%95%BF%22%5D%0A%20%20SLOW%20--%3E%20FAKE%5B%22%E6%A0%B7%E6%9C%AC%E5%86%85%20Z%20%E5%80%BC%E9%A2%91%E7%B9%81%E8%A7%A6%E5%8F%91%3A%20%E5%A4%8F%E6%99%AE%E8%99%9A%E9%AB%98%22%5D%0A%20%20FAKE%20--%3E%20PAIN%5B%22%E6%A0%B7%E6%9C%AC%E5%A4%96%E5%8D%95%E8%BE%B9%E8%B5%B0%E6%89%A9%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<p>上图回答的问题：秩选错时，两种偏差各自导向什么后果。选小是漏掉真关系（机会成本），选大是把噪声根当成关系（亏损风险）——由于样本外的单边走扩是实亏，交易约定宁可取小。</p><p>交易问题比检验问题更窄。你通常只想要 <strong>一条</strong> 组合，不是 \\(r\\) 条同时开仓。即便 \\(\\hat r=2\\)，也要在平面里再选方向：最小方差、最快误差修正、或与成本、流动性对齐。秩选择回答的是「空间有几维」，组合选择回答的是「这一维怎么张成」。把软件打印的「协整方程 1」当头号信号，是把特征根排序误读成夏普排序。</p><h3 id="顺序检验不是后验概率" tabindex="-1">顺序检验不是后验概率 <a class="header-anchor" href="#顺序检验不是后验概率" aria-label="Permalink to &quot;顺序检验不是后验概率&quot;">​</a></h3><p>迹的 \\(H_0:r\\le r_0\\) 是嵌套的。渐近水平是这条链上的，不是 \\(P(r=\\hat r\\mid\\mathrm{data})\\)。第一次不拒绝之后停下来，并不意味着更大的 \\(r\\) 被证伪得很强；功效不足时会系统性偏小。最大特征值一次只加一根，对「恰好多一条」更敏感，对「还剩好几条弱根」更钝。预先规定：主规则用迹、最大特征值作稳健性；两者差 1 时取较小的 \\(r\\)——交易上少一条假价差，比多一条近单位根更安全。不要看哪个 \\(p\\) 值更漂亮就取哪个。</p><p><span class="marginnote">确定性项的 case 必须先于秩选定死。价差若应在某水平摆动，把常数限制在协整内；让每条腿独立漂移，迹会更容易报出更高的 \\(r\\)，因为趋势被水平项吸收，看起来像多了一条「关系」。那条关系往往不可交易。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>检验路径。</strong> 先用信息准则选 VAR 滞后 \\(k\\)，再在预选的 Johansen case 下跑迹与最大特征值，报告 \\(r_0=0,\\ldots,p-1\\) 的统计量与临界值，而不是只报「软件选了 \\(r=2\\)」。邻近 \\(k\\) 上 \\(\\hat r\\) 若跳，说明识别不稳，应缩短篮子或先降维。小样本用 Bartlett 修正或 bootstrap 临界值，日频金融的名义 5% 不可当真。</p><p><strong>信息准则。</strong> Aznar–Salvador 等把秩选写成惩罚似然：更大的 \\(r\\) 改善拟合，但惩罚参数个数。准则相对顺序检验更少「第一次不拒绝」的路径依赖，但对惩罚系数敏感，同样会在 \\(N/T\\) 大时乱选。实务上把它当交叉验证：检验给出 \\(\\hat r_{\\mathrm{LR}}\\)，准则给出 \\(\\hat r_{\\mathrm{IC}}\\)，不一致则取小者，并降低杠杆。不要把准则最小的 \\(r\\) 直接映射成开仓条数。</p><p><strong>从秩到一条价差。</strong> 给定 \\(\\hat r\\)，施加经济约束（美元中性、对基准回归、排除某条不可空的腿）后得到 \\(\\hat\\beta\\)。若 \\(\\hat r\\gt 1\\)，在约束空间里解一个二次型：例如最小化 \\(\\beta&#39;\\hat\\Omega\\beta\\) 且 \\(\\beta\\) 在 \\(\\hat\\beta\\) 的列空间中，得到最低方差平稳组合；或最大化 \\(\\alpha\\) 方向上的调整速度。这是识别，不是再做一次迹检验。约束被似然比拒绝时，说明「你想交易的中性篮子不在协整空间」——仍可能有短持有回归，但不应引用 Johansen 的 \\(p\\) 值当许可。</p> \\[\\hat r=\\min\\bigl(\\hat r_{\\mathrm{trace}},\\hat r_{\\mathrm{maxeig}},\\hat r_{\\mathrm{IC}}\\bigr) \\quad\\text{再在 } \\mathrm{span}(\\hat\\beta)\\text{ 里选一条可执行方向。} \\]<p>取小不是定理，是交易上的保守约定，应在文档里写死。</p><h3 id="滚动秩与形成期冻结" tabindex="-1">滚动秩与形成期冻结 <a class="header-anchor" href="#滚动秩与形成期冻结" aria-label="Permalink to &quot;滚动秩与形成期冻结&quot;">​</a></h3><p>全样本 \\(\\hat r\\) 含未来。可复制的做法与 GGR 类似：形成期估秩与 \\(\\beta\\)，交易期冻结。滚动重估秩会使篮子维数跳，组合换手无经济含义——昨天 \\(r=1\\) 做一对，今天 \\(r=2\\) 突然多一条正交腿。若必须跟踪结构变化，应把「秩变化」当成 <a href="/quant/hedge-ratio-break">对冲比断裂</a> 一类的事件：先平仓，再在新形成期重估，而不是让仓位在维数跳变时连续变形。</p><p>高维时先降维再 Johansen：行业指数、前几个主成分、或流动性最好的 \\(p\\le 5\\) 只。\\(p=10\\)、\\(T=250\\) 的迹几乎不可用。这与 <a href="/quant/pca-residual-basket">篮子 PCA 残差</a> 的分工是：PCA 不声称 \\(I(0)\\)，Johansen 声称但维数必须小。</p><p><span class="marginnote">数字实例：\\(p=10\\)、滞后 1 的 VAR，仅自回归系数就有 \\(10\\times 10=100\\) 个要估，250 个观测摊下来每个系数平均只摊到两三个自由度，临界值自然失真。降到 \\(p=5\\) 后参数砍掉四分之三以上，同样的样本长度才够检验「站得住」。</span></p><p><span class="marginnote">\\(\\alpha\\) 接近 0 的关系在样本内可以像协整（残差像平稳），预测上几乎不回调。选秩之后必须看载荷：没有误差修正的「平稳组合」是统计假象或极慢的根，不该占用名义。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>高斯 VAR 的似然只通过残差协方差与 \\(\\Pi\\) 的秩依赖数据。把 \\(r\\) 提高，是允许更多水平通道进入差分的条件均值，拟合必然变好。惩罚或临界值是在拦「把噪声根当成通道」。金融日频里噪声根很多：短期相关、异方差、跳跃都会抬高小特征根，使迹偏爱更大的 \\(r\\)。因此交易用的秩应系统性小于检验在名义 5% 上给出的秩——你要的是强通道，不是全部不能拒绝的通道。</p><p>机制上，秩还决定对冲比的自由度。\\(r=1\\) 时 \\(\\beta\\) 只识别到一条线（再加规范化）；\\(r=2\\) 时有一个平面的等价类，未约束的两条特征向量会在样本间旋转，换手巨大。这就是为什么 \\(\\hat r\\gt 1\\) 时必须加经济约束或二次型选择：不是为了好看，是为了让 \\(\\beta\\) 可复制。没有这一步，篮子 PCA 往往比未约束 Johansen 更稳，因为主成分有正交和方差排序，尽管它们不是协整向量。</p><p><span class="marginnote">常见误区：初学者看到软件打印「协整方程 1」就当成最值得交易的方向。特征向量的排序按特征根大小，与夏普排序毫无关系；真正该做的是在 \\(\\hat r\\) 定下后，于约束空间里再选一次——例如挑方差最低或误差修正最快的那条组合，而不是沿用软件的第一行输出。</span></p><h3 id="过拟合-如何表现为假-alpha" tabindex="-1">过拟合 \\(r\\) 如何表现为假 alpha <a class="header-anchor" href="#过拟合-如何表现为假-alpha" aria-label="Permalink to &quot;过拟合 $r$ 如何表现为假 alpha&quot;">​</a></h3><p>样本内 \\(r\\) 偏大，会多出一条「价差」在形成期来回摆，Z-score 频繁触发，夏普虚高。样本外该方向继续像单位根，开仓后单边走扩，时间止损在最宽处成交。这与协整破裂不同：破裂是真关系断了；过拟合秩是关系从来不够强。诊断是形成期 \\(\\hat\\kappa\\) 已经很小、或残差 ADF 只在估计的 \\(\\beta\\) 上勉强拒绝。对这种方向，正确动作是丢掉，而不是加宽阈值硬做。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在未固定 \\(k\\) 与确定性项之前比较不同篮子的 \\(\\hat r\\)。不要把 \\(p\\) 只股票的 \\(\\hat r=3\\) 当成三个独立策略同时加杠杆——估计误差相关。不要用全样本迹给交易期背书。厚尾与结构断裂使检验过拒或乱跳，应分割样本；前半 \\(r=1\\)、后半 \\(r=0\\) 时，合并的 \\(\\hat r\\) 没有交易含义。</p><p>与 Engle–Granger 的分工：两资产、要报告一个对冲比，用两步，\\(r\\) 不是选择变量。多腿、要约束、要问有几条长期关系，用 Johansen，然后用本篇的保守规则落到一条可执行价差。指数套利还要处理成分股更换，秩在调仓日应视为未知，先平再估。A 股停牌会使某条腿的水平冻结，特征根扭曲，形成期必须剔除或插值规则事先写死。</p><p><span class="marginnote">Johansen（1991）的渐近是 \\(T\\to\\infty\\)、阶数正确、新息高斯 iid。把 \\(\\hat r\\) 写成「市场承认有 \\(r\\) 条套利关系」是把检验当成了定价理论。秩是统计维数，套利还要成本、借券与同步成交。</span></p>',26)),(e(),o(B,null,{default:t(()=>[s(n,{id:"mermaid-93",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22p%20%E7%BB%B4%20I(1)%20%E7%AF%AE%E5%AD%90%22%5D%20--%3E%20K%5B%22%E9%80%89%E6%BB%9E%E5%90%8E%20k%20%E4%B8%8E%E7%A1%AE%E5%AE%9A%E6%80%A7%E9%A1%B9%22%5D%0A%20%20K%20--%3E%20TR%5B%22%E8%BF%B9%20%2F%20%E6%9C%80%E5%A4%A7%E7%89%B9%E5%BE%81%E5%80%BC%20%2F%20IC%22%5D%0A%20%20TR%20--%3E%20R%5B%22%E4%BF%9D%E5%AE%88%E5%8F%96%E8%BE%83%E5%B0%8F%E7%9A%84%20r%22%5D%0A%20%20R%20--%3E%20SP%5B%22span(%CE%B2)%20%E5%8A%A0%E7%BB%8F%E6%B5%8E%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20SP%20--%3E%20DIR%5B%22%E9%80%89%E4%B8%80%E6%9D%A1%3A%20%E6%9C%80%E5%B0%8F%E6%96%B9%E5%B7%AE%E6%88%96%E6%9C%80%E5%BF%AB%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20DIR%20--%3E%20OU%5B%22%E5%9C%A8%E8%AF%A5%E4%BB%B7%E5%B7%AE%E4%B8%8A%E4%BC%B0%20%CE%BA%22%5D%0A%20%20OU%20--%3E%20GATE%7B%22%CE%BA%20%E8%B6%B3%E5%A4%9F%E5%A4%A7%E4%B8%94%20%CE%B1%20%E6%98%BE%E8%91%97%3F%22%7D%0A%20%20GATE%20--%3E%7C%E5%90%A6%7C%20DROP%5B%22%E4%B8%A2%E6%8E%89%E8%AF%A5%E6%96%B9%E5%90%91%22%5D%0A%20%20GATE%20--%3E%7C%E6%98%AF%7C%20TRD%5B%22%E5%86%BB%E7%BB%93%20%CE%B2%2C%20%E8%BF%9B%E5%85%A5%E4%BA%A4%E6%98%93%E6%9C%9F%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r("h2",{id:"小结",tabindex:"-1"},[E("小结 "),r("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=r("ul",null,[r("li",null,"协整秩是空间维数，不是开仓条数；\\(\\hat r\\gt 1\\) 时必须在空间里再选一条可执行方向。"),r("li",null,"迹与最大特征值、信息准则不一致时，交易上取较小的 \\(r\\)，少做近单位根。"),r("li",null,"形成期估秩、交易期冻结；滚动让 \\(r\\) 跳变应视为事件，先平仓再重估。"),r("li",null,"过拟合 \\(r\\) 会在样本内制造假回归、样本外单边走扩，与协整破裂不是同一诊断。"),r("li",null,[E("出处：Johansen, 1988/1991；秩的信息准则见 Aznar and Salvador, 2002；检验细节见 "),r("a",{href:"/quant/johansen"},"Johansen"),E("。")])],-1))])}const f=l(i,[["render",d]]);export{_ as __pageData,f as default};
